<div class="modal-head"><h2>{{ $material?'Editar material':'Nuevo material' }}</h2><button type="button" data-modal-close>×</button></div><div class="field-grid"><div class="field"><label>Nombre *</label><input name="name" value="{{ old('name',$material?->name) }}" required></div><div class="field"><label>Categoría *</label><select name="category"><option @selected($material?->category==='Tela')>Tela</option><option @selected($material?->category==='Sintético')>Sintético</option><option @selected($material?->category==='Cuero')>Cuero</option><option @selected($material?->category==='Relleno')>Relleno</option><option @selected($material?->category==='Accesorio')>Accesorio</option></select></div><div class="field"><label>Nombre del color *</label><input name="color" value="{{ old('color',$material?->color) }}" placeholder="Ej.: Café claro" required></div><div class="field"><label>Color visual *</label><input type="color" name="visual_color" value="{{ old('visual_color',$material?->color_hex ?? '#B88A5A') }}" required></div><div class="field"><label>Unidad</label><select name="unit"><option @selected($material?->unit==='metro')>metro</option><option @selected($material?->unit==='plancha')>plancha</option><option @selected($material?->unit==='unidad')>unidad</option></select></div><div class="field"><label>Precio unitario (Bs)</label><input type="number" step="0.01" min="0" name="unit_price" value="{{ old('unit_price',$material?->unit_price ?? 0) }}" required></div><div class="field"><label>Existencia actual</label><input type="number" step="0.01" min="0" name="stock" value="{{ old('stock',$material?->stock ?? 0) }}" required></div><div class="field"><label>Alerta mínima</label><input type="number" step="0.01" min="0" name="minimum_stock" value="{{ old('minimum_stock',$material?->minimum_stock ?? 5) }}" required></div><input type="hidden" name="active" value="1"><div class="field full"><button class="btn btn-primary">Guardar material</button></div></div>
